import React from "react";
import { Link } from "gatsby";

const Navbar: React.FC = () => {
  const pathPrefix = typeof window !== 'undefined' 
    ? window.location.pathname.split('/')[1] 
    : '';
  
  const resumeUrl = pathPrefix && pathPrefix !== '' 
    ? `/${pathPrefix}/Josh_Scragg_Resume.pdf`
    : `/Josh_Scragg_Resume.pdf`;

  return (
    <nav className="left-section">
      <Link to="/" className="button"><h1>Josh Scragg</h1></Link>
      <Link to="/aboutpage" className="button nav">About</Link>
      <Link to="/projects" className="button nav">Projects</Link>
      <a 
        href={resumeUrl}
        className="button nav" 
        target="_blank" 
        rel="noopener noreferrer"
      >
        Resume
      </a>
    </nav>
  );
};

export default Navbar;